import json
B = json.load(open("out/v3_bom.json")); R = B["best"]; V = json.load(open("out/v3_verify.json")); T = json.load(open("out/v3_rotor.json")); g = {}
for r in B["items"]: g.setdefault(r["group"], []).append(r)
md = ["# Punta Mita wind machine v3", "", "10 m, three-blade laminated wood rotor on a 12 m steel tripod bolted to a concrete pad. Supersedes `BUILD_V2.md`.", "", "![CAD](cad3/iso.png)", "",
 f"- **Output:** {R['W']:.0f} W average, {R['W']*8.766:,.0f} kWh a year (simulated, NASA POWER wind, Cp capped at 0.38).", f"- **Parts:** about ${R['capex']:,.0f}, of which ${R['seen']:,.0f} is at prices seen on seller pages. The rest is estimated. Labour is not included.", f"- **Cost of energy:** ${R['u20']:.0f}/MWh over 20 years, ${R['u5']:.0f} over 5, ${R['u20w']:.0f} over 20 at 1.3x wind. Hot water: ${R['heat20']:.0f}/MWh.", "- **Target of $10/MWh is not reached.**", "",
 f"Blade: chord {T['chord'][0]} to {T['chord'][1]} m, thickness {T['thick'][0]*1000:.0f} to {T['thick'][1]*1000:.0f} mm, twist {T['twist'][0]} to {T['twist'][1]} degrees, 5 degree cone.", "", "## Structural simulation (12 wind directions)", "", "| Case | Lowest safety factor | Where | Pull per foot |", "|---|---|---|---|"] + [f"| {c['name']} | {c['sf']:.2f} | {c['where']} | {c['pull_kg']:.0f} kg |" for c in V["cases"]] + ["",
 f"Tower bending {V['tower_hz'][0]:.1f} Hz and tail {V['tail_hz']:.1f} Hz are clear of the 1.3 Hz maximum once-per-turn rotor speed. The pad and machine must weigh at least {V['pad_t']:.1f} t. The trailer spindle needs the yaw damper (safety factor 1.65 at 0.2 rad/s).", "", "## Order list", ""]
for n, rs in g.items(): md += [f"### {n} (about ${sum(r['usd'] for r in rs):,.0f})", "", "| Item | Qty | Unit | Price |", "|---|---|---|---|"] + [f"| {r['item']} | {r['qty']} | {'MX$' if r['cur']=='MXN' else '$'}{r['unit']:,.2f} | {r['status']} |" for r in rs] + [""]
md += ["## Not verified", "", "- Laminated blade strength, glue lines, welds, pipe splices and fatigue are assumed or not simulated.", "- Furling, yaw damping and braking have not been dynamically simulated.", "- Pad weight, condition and anchor pull-out must be checked on site.", "- Lower the tower before any tropical storm. Raising a 12 m tower with a 215 kg rotor can kill someone: use a rigger, a winch and a clear fall zone.", ""]
open("BUILD_V3.md", "w").write("\n".join(md))
